import{_ as t,o as s,c as o,a2 as n}from"./chunks/framework.Desnpdez.js";const g=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"help/troubleshooting.md","filePath":"help/troubleshooting.md"}'),a={name:"help/troubleshooting.md"};function i(r,e,l,d,h,p){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Work through the symptom that matches yours.</p><h2 id="macos-quarantine" tabindex="-1">macOS quarantine (“damaged” or “can’t be opened”) <a class="header-anchor" href="#macos-quarantine" aria-label="Permalink to &quot;macOS quarantine (“damaged” or “can’t be opened”) {#macos-quarantine}&quot;">​</a></h2><p>Release <strong><code>.dmg</code></strong> files are <strong>not notarized</strong>. Browsers tag downloads with <strong>quarantine</strong>, so Gatekeeper may block the app until you clear it or use the install script.</p><h3 id="recommended-one-line-install-download-copy-quarantine" tabindex="-1">Recommended: one-line install (download + copy + quarantine) <a class="header-anchor" href="#recommended-one-line-install-download-copy-quarantine" aria-label="Permalink to &quot;Recommended: one-line install (download + copy + quarantine)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://halfcross.github.io/mbit-mcpo-proxy-download/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>The script downloads the latest <code>.dmg</code> from <a href="https://github.com/halfcross/mbit-mcpo-proxy-download/releases" target="_blank" rel="noreferrer">GitHub Releases</a>, copies <strong>MindBehindAI</strong> to <strong>Applications</strong>, and clears quarantine on the app bundle.</p><h3 id="manual-install-drag-from-dmg" tabindex="-1">Manual install (drag from <code>.dmg</code>) <a class="header-anchor" href="#manual-install-drag-from-dmg" aria-label="Permalink to &quot;Manual install (drag from `.dmg`)&quot;">​</a></h3><ol><li>Download the <code>.dmg</code> from <a href="https://github.com/halfcross/mbit-mcpo-proxy-download/releases" target="_blank" rel="noreferrer">Releases</a> or the <a href="https://halfcross.github.io/mbit-mcpo-proxy-download/" target="_blank" rel="noreferrer">download page</a>.</li><li>Open the disk image and drag <strong>MindBehindAI</strong> to <strong>Applications</strong>.</li><li>If macOS says the app is damaged or cannot be opened, remove quarantine once (adjust the path if needed):</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">APP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/Applications/MindBehindAI.app&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> f</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\)</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APP</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> l</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> {}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span></code></pre></div><p>Avoid plain <code>xattr -cr</code> on this bundle: it follows symlinks, and bundled Node’s <code>bin/npx</code> / <code>npm</code> / <code>corepack</code> point into <code>lib/node_modules/…</code>. If that subtree is absent for one architecture, <code>xattr</code> reports “No such file” and may fail the whole command. On macOS, <strong><code>xattr -c -s</code></strong> clears extended attributes <strong>on the symlink inode</strong> (<code>-s</code>); do <strong>not</strong> use <code>-h</code> here — with BSD <code>xattr</code>, <strong><code>-h</code> prints help</strong>, not “don’t follow”.</p><p>You can also try <strong>System Settings → Privacy &amp; Security → Open Anyway</strong> once after the first launch attempt.</p><h2 id="windows" tabindex="-1">Windows — SmartScreen, slow start, and Defender <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows — SmartScreen, slow start, and Defender {#windows}&quot;">​</a></h2><p>MindBehindAI for Windows ships as a <strong>portable <code>.exe</code></strong> (no installer). Builds are <strong>not code-signed</strong> yet, so Windows may show extra warnings and scan the app heavily on first launch. That is expected and safe if you downloaded from the official release page.</p><h3 id="smartscreen-windows-protected-your-pc-unknown-publisher" tabindex="-1">SmartScreen (“Windows protected your PC” / unknown publisher) <a class="header-anchor" href="#smartscreen-windows-protected-your-pc-unknown-publisher" aria-label="Permalink to &quot;SmartScreen (“Windows protected your PC” / unknown publisher)&quot;">​</a></h3><ol><li>Download only from <strong><a href="https://github.com/halfcross/mbit-mcpo-proxy-download/releases" target="_blank" rel="noreferrer">GitHub Releases</a></strong> (or the <a href="https://halfcross.github.io/mbit-mcpo-proxy-download/" target="_blank" rel="noreferrer">download page</a> link that points there).</li><li>Double-click <code>MindBehindAI-&lt;version&gt;-portable-x64.exe</code>.</li><li>If SmartScreen blocks the app: click <strong>More info</strong> → <strong>Run anyway</strong>.</li></ol><p>There is no separate “Trust publisher” step until the app is signed with a commercial certificate. Self-signed certificates do <strong>not</strong> remove this warning for public downloads.</p><h3 id="first-start-feels-slow-10–30-seconds-no-window" tabindex="-1">First start feels slow (10–30 seconds, no window) <a class="header-anchor" href="#first-start-feels-slow-10–30-seconds-no-window" aria-label="Permalink to &quot;First start feels slow (10–30 seconds, no window)&quot;">​</a></h3><p>The portable file <strong>unpacks a large bundle</strong> (assistant bridge, runtimes, optional agent tools) into your user temp folder. <strong>Microsoft Defender</strong> often scans that folder at the same time, which can take <strong>20–30 seconds</strong> on the <strong>first</strong> run after download.</p><ul><li><strong>Second and later starts</strong> of the same version are usually much faster (same unpack folder is reused).</li><li>In <strong>Task Manager</strong>, you may see <strong>Antimalware Service Executable</strong> with high CPU during this phase—that is normal.</li></ul><p>If the app seems to run but <strong>no window appears</strong>, reset saved window position:</p><ol><li>Quit MindBehindAI (tray icon → <strong>Quit</strong>, or end the task in Task Manager).</li><li>Delete <code>%APPDATA%\\MindBehind\\mcp-orchestrator\\shell-ui-prefs.json</code>.</li><li>Start the portable <code>.exe</code> again.</li></ol><h3 id="recommended-microsoft-defender-exclusions-optional-it-friendly" tabindex="-1">Recommended Microsoft Defender exclusions (optional, IT-friendly) <a class="header-anchor" href="#recommended-microsoft-defender-exclusions-optional-it-friendly" aria-label="Permalink to &quot;Recommended Microsoft Defender exclusions (optional, IT-friendly)&quot;">​</a></h3><p>Adding exclusions is <strong>optional</strong> but often cuts first-start time and repeated scans. Use only paths you trust (official download). Replace <code>&lt;YourUser&gt;</code> with your Windows sign-in name and <code>&lt;version&gt;</code> with the release you installed (for example <code>5.2.3</code>).</p><table tabindex="0"><thead><tr><th>What to exclude</th><th>Path or item</th><th>Why</th></tr></thead><tbody><tr><td><strong>Portable app</strong> (file)</td><td>Folder where you saved the <code>.exe</code>, e.g. <code>C:\\Users\\&lt;YourUser&gt;\\Downloads\\MindBehindAI-&lt;version&gt;-portable-x64.exe</code></td><td>Avoids rescanning the download on every launch</td></tr><tr><td><strong>Unpack folder</strong> (folder)</td><td><code>%TEMP%\\MindBehindAI</code> — typically <code>C:\\Users\\&lt;YourUser&gt;\\AppData\\Local\\Temp\\MindBehindAI</code></td><td>Portable edition extracts the bundle here</td></tr><tr><td><strong>App data</strong> (folder)</td><td><code>%APPDATA%\\MindBehind\\mcp-orchestrator</code> — <code>C:\\Users\\&lt;YourUser&gt;\\AppData\\Roaming\\MindBehind\\mcp-orchestrator</code></td><td>Settings, license storage, logs, connection config</td></tr></tbody></table><p><strong>Steps (Windows 11; Windows 10 is similar):</strong></p><ol><li>Open <strong>Settings</strong> → <strong>Privacy &amp; security</strong> → <strong>Windows Security</strong> → <strong>Virus &amp; threat protection</strong>.</li><li>Under <strong>Virus &amp; threat protection settings</strong>, choose <strong>Manage settings</strong>.</li><li>Scroll to <strong>Exclusions</strong> → <strong>Add or remove exclusions</strong> → <strong>Add an exclusion</strong>.</li><li>Add the <strong>File</strong> (your <code>.exe</code>), then <strong>Folder</strong> entries for <code>%TEMP%\\MindBehindAI</code> and <code>%APPDATA%\\MindBehind\\mcp-orchestrator</code> as above.</li></ol><p>If your organization uses <strong>Defender for Endpoint</strong> or another antivirus, ask IT to allow the same paths or the process <strong>MindBehindAI.exe</strong> under your standard software-request process.</p><h3 id="windows-ui-notes" tabindex="-1">Windows UI notes <a class="header-anchor" href="#windows-ui-notes" aria-label="Permalink to &quot;Windows UI notes&quot;">​</a></h3><ul><li>The app uses a <strong>custom title bar</strong> (like macOS), not the classic <strong>File / Edit / View</strong> menu inside the window.</li><li><strong>Quit</strong> is available from the <strong>tray icon</strong> (notification area) if the window is closed.</li></ul><h2 id="bridge-will-not-start" tabindex="-1">Bridge will not start <a class="header-anchor" href="#bridge-will-not-start" aria-label="Permalink to &quot;Bridge will not start&quot;">​</a></h2><ol><li>On <strong>Home</strong>, read the <strong>Built-in engine</strong> step—if it says unavailable, reinstall or contact support with the exact text.</li><li>Check <strong>Logs</strong> for <code>address already in use</code>—another program is using the HTTP port. Change <strong>Settings → HTTP port</strong> or quit the other program.</li><li>Tap <strong>Apply changes</strong> on Home after large edits under <strong>Connections</strong>.</li></ol><h2 id="tools-missing-in-open-webui" tabindex="-1">Tools missing in Open WebUI <a class="header-anchor" href="#tools-missing-in-open-webui" aria-label="Permalink to &quot;Tools missing in Open WebUI&quot;">​</a></h2><ol><li>Confirm the bridge is <strong>Running</strong> on <strong>Home</strong>.</li><li>Confirm each connection is <strong>enabled</strong> under <strong>My connections</strong>.</li><li>Re-run <strong>Sync enabled connections</strong> on <strong>Integrations → Open WebUI</strong> after editing connections.</li><li>For manual setup, re-copy each <strong>Copy link</strong>—URLs change if you rename a connection.</li></ol><h2 id="oauth-loops-or-expired-login" tabindex="-1">OAuth loops or expired login <a class="header-anchor" href="#oauth-loops-or-expired-login" aria-label="Permalink to &quot;OAuth loops or expired login&quot;">​</a></h2><ol><li>Clear <strong>Settings → OAuth tokens</strong>, then trigger sign-in again from your assistant so the browser opens fresh.</li><li>Make sure pop-up blockers are not blocking the Telekom or Microsoft login window.</li></ol><h2 id="docker-required-preset-fails" tabindex="-1">Docker-required preset fails <a class="header-anchor" href="#docker-required-preset-fails" aria-label="Permalink to &quot;Docker-required preset fails&quot;">​</a></h2><p>Install <strong>Docker Desktop</strong> and wait until it is healthy, then retry the preset. The bridge itself does not run inside Docker.</p><h2 id="agents-paperclip" tabindex="-1">Agents (experimental) — first start slow or fails <a class="header-anchor" href="#agents-paperclip" aria-label="Permalink to &quot;Agents (experimental) — first start slow or fails {#agents-paperclip}&quot;">​</a></h2><p>The <strong>Agents</strong> feature (enable under <strong>Settings → Experimental</strong>) downloads and builds the <a href="https://github.com/paperclipai/paperclip" target="_blank" rel="noreferrer">Paperclip</a> server on <strong>first start</strong>, into your app data folder (not inside the <code>.app</code> / portable bundle). This keeps release downloads smaller.</p><h3 id="what-to-expect" tabindex="-1">What to expect <a class="header-anchor" href="#what-to-expect" aria-label="Permalink to &quot;What to expect&quot;">​</a></h3><ul><li><strong>First start</strong> after enabling Agents: <strong>5–15 minutes</strong>, steady network use, and several GB of disk under your MindBehind data directory. Use <strong>Start</strong> on the Agents page; open <strong>View logs</strong> to see install progress.</li><li><strong>Later starts</strong> reuse the installed runtime and should be quick unless the app version pins a new Paperclip release.</li></ul><h3 id="install-fails-or-hangs" tabindex="-1">Install fails or hangs <a class="header-anchor" href="#install-fails-or-hangs" aria-label="Permalink to &quot;Install fails or hangs&quot;">​</a></h3><ol><li>Confirm <strong>internet access</strong> to <code>github.com</code> (corporate proxies may block <code>git</code>/<code>pnpm</code> downloads).</li><li>Read the last lines on the <strong>Agents</strong> log tab or <strong>Logs → Agents</strong>.</li><li>Quit the app, delete only the partial install folder if support asks you to reset it: <ul><li>macOS: <code>~/Library/Application Support/MindBehind/mcp-orchestrator/paperclip/runtime</code> (path may vary slightly by edition)</li><li>Windows: <code>%APPDATA%\\MindBehind\\mcp-orchestrator\\paperclip\\runtime</code></li></ul></li><li>Start Agents again.</li></ol><p>On <strong>Windows</strong>, Defender may scan heavily while files are written under <code>%APPDATA%</code>; see <a href="#windows">Windows Defender exclusions</a> if IT allows path exclusions.</p><p>For local development, you can still pre-bundle with <code>npm run bundle:paperclip</code> in <code>electron-app/</code> so <code>resources/paperclip/</code> is used without a first-run download.</p><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck&quot;">​</a></h2><p>Collect three things before contacting support:</p><ol><li>A screenshot of <strong>Home</strong> (status strip visible).</li><li>The last ~30 lines from <strong>Logs</strong>.</li><li>Your OS and version (macOS: Apple Silicon or Intel; Windows: edition and 64-bit).</li></ol><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><strong><a href="./faq.html">FAQ</a></strong></li><li><strong><a href="./../everyday/home.html">Home</a></strong></li></ul>',51)])])}const u=t(a,[["render",i]]);export{g as __pageData,u as default};
